# Generated from ClickHouse catalog metadata; review suggested measures.
from hypequery.datasets import dataset, dimension, measure

datasets = {
    'order_events': dataset(
        name='order_events',
        source='analytics.order_events',
        time_key='created_at',
        dimensions={
            'orderId': dimension.number(column='order_id', label='Order Id'),
            'netAmount': dimension.number(column='net_amount', label='Net Amount'),
            'createdAt': dimension.timestamp(column='created_at', label='Created At'),
            'updatedAt': dimension.timestamp(column='updated_at', label='Updated At'),
            'latitude': dimension.number(column='latitude', label='Latitude'),
            'tenantId': dimension.string(column='tenant_id', label='Tenant Id'),
            'isPaid': dimension.boolean(column='is_paid', label='Is Paid'),
        },
        measures={
            "totalCount": measure.count('netAmount', label="Total Count"),
            'totalNetAmount': measure.sum('netAmount', label='Total Net Amount'),
            'avgNetAmount': measure.avg('netAmount', label='Average Net Amount'),
        },
    ),
    'sessions': dataset(
        name='sessions',
        source='analytics.sessions',
        dimensions={
            'sessionId': dimension.string(column='session_id', label='Session Id'),
            'started': dimension.timestamp(column='started', label='Started'),
            'ended': dimension.timestamp(column='ended', label='Ended'),
            'durationMs': dimension.number(column='duration_ms', label='Duration Ms'),
            'orgId': dimension.string(column='org_id', label='Org Id'),
        },
        measures={
            "totalCount": measure.count('started', label="Total Count"),
            'totalDurationMs': measure.sum('durationMs', label='Total Duration Ms'),
            'avgDurationMs': measure.avg('durationMs', label='Average Duration Ms'),
        },
    ),
    'lookups': dataset(
        name='lookups',
        source='analytics.lookups',
        dimensions={
            'code': dimension.string(column='code', label='Code'),
        },
        measures={
            "totalCount": measure.count('code', label="Total Count"),
        },
    ),
}

